SourceCode.Declaration:
class TFMListElement extends TFMListBase
{
    TFMListXAlign horizontalAlignment;
    TFMListYAlign verticalAlignment;

}

Method.Source:
/// <summary>
///
/// </summary>
public void new()
{
    super();
    horizontalAlignment = SysChartHorizontalAlignment::Left;
    verticalAlignment = TFMVerticalAlignment::Top;
}

[TFMParameter(SysChartHorizontalAlignment::Left,'','')]
public TFMListXAlign parmHorizontalAlignment(TFMListXAlign _horizontalAlignment = horizontalAlignment)
{
    horizontalAlignment = _horizontalAlignment;
    return horizontalAlignment;
}

[TFMParameter(TFMVerticalAlignment::Top,'','')]
public TFMListYAlign parmVerticalAlignment(TFMListYAlign _verticalAlignment = verticalAlignment)
{
    verticalAlignment = _verticalAlignment;
    return verticalAlignment;
}
